      nCopyIdx = nLine;
      Storm::Source::SSTR::SStrPrintf(szFormattedMessageBuffer, 0x1000, "--------  FILE: %s    LINE: %d  --------\n\n", StripPathPrefixToRelative(szText), nCopyIdx);
